import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

class Counter100 {
    var current: Int by Delegates.observable(38) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
fun <T> List<T>.secondOrNull101(): T? = if (size > 1) this[1] else null

fun render101(values: List<String>?): String {
    return values?.filter { it.isNotBlank() }?.joinToString(separator = ",") ?: "empty"
}
sealed class Outcome102 {
    data class Success(val payload: String) : Outcome102()
    data object Failure : Outcome102()
}

fun describe102(outcome: Outcome102): String = when (outcome) {
    is Outcome102.Success -> outcome.payload
    Outcome102.Failure -> "failed"
}
